import { test, expect } from '@playwright/test';

test.describe('Mobile Checkout Form Stacking', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/checkout');
  });

  test('should stack checkout form vertically on mobile screens', async ({ page }) => {
    // Set viewport to mobile size
    await page.setViewportSize({ width: 375, height: 812 });

    // Verify form is stacked vertically
    const cartItemCount = page.getByRole('heading', { name: /cart items/i });
    await expect(cartItemCount).toBeVisible();

    const shippingAddress = page.getByRole('fieldset', { name: /shipping address/i });
    await expect(shippingAddress).toBeVisible();

    const billingAddress = page.getByRole('fieldset', { name: /billing address/i });
    await expect(billingAddress).toBeVisible();

    const shippingInfo = page.getByRole('fieldset', { name: /shipping info/i });
    await expect(shippingInfo).toBeVisible();

    const shippingMethod = page.getByRole('fieldset', { name: /shipping method/i });
    await expect(shippingMethod).toBeVisible();

    const paymentDetails = page.getByRole('fieldset', { name: /payment details/i });
    await expect(paymentDetails).toBeVisible();

    const checkoutButton = page.getByRole('button', { name: /checkout/i });
    await expect(checkoutButton).toBeVisible();

    // Verify form elements are stacked vertically
    const formLayout = page.getByRole('form');
    await expect(formLayout).toHaveClass(/stacked-vertical/);

    // Verify form is responsive and stacks correctly
    await page.evaluate(() => {
      window.innerWidth = 375;
      window.innerHeight = 812;
    });

    const formLayoutAfterResize = page.getByRole('form');
    await expect(formLayoutAfterResize).toHaveClass(/stacked-vertical/);
  });

  test('should maintain form layout on tablet screens', async ({ page }) => {
    // Set viewport to tablet size
    await page.setViewportSize({ width: 768, height: 1024 });

    // Verify form is still stacked vertically
    const cartItemCount = page.getByRole('heading', { name: /cart items/i });
    await expect(cartItemCount).toBeVisible();

    const shippingAddress = page.getByRole('fieldset', { name: /shipping address/i });
    await expect(shippingAddress).toBeVisible();

    const billingAddress = page.getByRole('fieldset', { name: /billing address/i });
    await expect(billingAddress).toBeVisible();

    const shippingInfo = page.getByRole('fieldset', { name: /shipping info/i });
    await expect(shippingInfo).toBeVisible();

    const shippingMethod = page.getByRole('fieldset', { name: /shipping method/i });
    await expect(shippingMethod).toBeVisible();

    const paymentDetails = page.getByRole('fieldset', { name: /payment details/i });
    await expect(paymentDetails).toBeVisible();

    const checkoutButton = page.getByRole('button', { name: /checkout/i });
    await expect(checkoutButton).toBeVisible();

    // Verify form is responsive and maintains layout
    const formLayout = page.getByRole('form');
    await expect(formLayout).toHaveClass(/stacked-vertical/);

    // Verify form elements are still stacked vertically
    const formLayoutAfterResize = page.getByRole('form');
    await expect(formLayoutAfterResize).toHaveClass(/stacked-vertical/);
  });
});
